'use strict';
const {Game,COLORS}=DealEngine;let game=null,selected=null,selectedOwner=0,botTimer=null,menuOpen=true,modalLocked=false;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let speed=1500;let reduced=!!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function localStorageSafe(k,v){try{if(v!==undefined)localStorage.setItem(k,v);else return localStorage.getItem(k)}catch{}}
function toast(t){$('#notifications').innerHTML='<div class="toast">'+esc(t)+'</div>';setTimeout(()=>$('#notifications').innerHTML='',3500)}
function def(c){return game?game.d(c):DECK.find(d=>d.key===c.key)}function bank(i){return visibleBank(i).reduce((s,c)=>s+def(c).value,0)}
function art(c){return ART[c.key]}function card(c,owner=0,where='field',size=''){let d=def(c);return `<button data-card-id="${c.id}" class="card ${selected?.id===c.id?'selected':''}" ${size?`style="width:${size}px"`:''} ${owner===0&&where==='field'&&['property','wild'].includes(d.type)&&game.find(0,c.id)?`draggable="false" data-prop="${c.id}"`:""} onclick="inspect('${c.id}',${owner},'${where}')" title="${esc(d.name)} — ${d.value}M" aria-label="${esc(d.name)}, ${d.value} million"><img class="${orientation(c,owner)}" src="${art(c)}" alt="${esc(d.name)}" draggable="false">${c.locked?`<span class="lock">🔒 ${esc(c.locked)}</span>`:''}</button>`}
const WILD_TOP={pink_orange_wildcard:'Pink',brown_light_blue_wildcard:'Brown',light_blue_railroad_wildcard:'Light Blue',red_yellow_wildcard:'Red',dark_blue_green_wildcard:'Dark Blue',green_railroad_wildcard:'Green',railroad_utility_wildcard:'Railroad'};
function wildFlipped(c,owner=0,color){let top=WILD_TOP[c.key];if(!top)return false;let active=color||game?.find(owner,c.id)?.group?.color||c.locked;return !!active&&active!==top}
function orientation(c,owner=0,color){return wildFlipped(c,owner,color)?'inverted':''}
function findAny(id,i){let p=game.p(i);return [...p.hand,...p.bank,...p.special,...p.groups.flatMap(g=>[...g.cards,g.house,g.hotel].filter(Boolean))].find(c=>c.id===id)}
function save(){if(game&&!onlineSession)localStorageSafe('kaze_deal_save',JSON.stringify(game.s))}
function canResume(){try{let s=JSON.parse(localStorageSafe('kaze_deal_save')||'null');return s?.version===1&&s.players?.length>=2}catch{return false}}
function menu(){if(onlineSession){onlineStream?.close();onlineSession=null;onlineView=null;}closeCardPreview();clearFeedback();menuOpen=true;clearTimeout(botTimer);$('#playReveal')?.remove();document.querySelector('.your-turn-notice')?.remove();closeModal();$('#root').innerHTML=`<main class="menu"><div class="menuhero"><img src="${ART.logo}" alt="Monopoly Deal Lvl. Up — made by Kaze"><p class="eyebrow">Your empire. One rotation to defend it.</p></div><section class="menucopy"><div class="eyebrow">Local edition · 130 cards</div><h1>Build it.<br>Steal it.<br><span style="color:#efc46f">Hold it.</span></h1><p>Collect three different complete property sets, then defend them until your next turn. Play offline against bots using Kaze’s custom deck.</p><div class="settingsbox form"><label>Opponents<select id="botCount"><option value="1">1 bot · quick duel</option><option value="2" selected>2 bots · classic table</option><option value="3">3 bots · busy table</option><option value="4">4 bots · full table</option></select></label><p>Bot pace: Relaxed</p></div><div class="menubuttons"><button class="gold start" onclick="newGame()">Start local game →</button><button class="quiet" onclick="onlineMenu()">Online lobby · 5 slots</button><button class="quiet" onclick="resume()" ${canResume()?'':'disabled'}>Continue game</button><button class="quiet" onclick="rules()">How to play</button><button class="quiet" onclick="audit()">Card library & values</button><button class="quiet" onclick="settings()">Settings</button></div><p style="font-size:11px;margin-top:16px">made by Kaze · Local + online edition v2.6<br>Local play runs offline. Online rooms use the included server.</p></section></main>`}
function newGame(){onlineStream?.close();onlineSession=null;onlineView=null;let n=Number($('#botCount').value)+1;speed=1500;localStorageSafe('deal_speed',speed);game=new Game(DECK,n);resetFeedback(0);boardPlay=null;lastTurnNotice=null;selected=null;menuOpen=false;save();render();toast('First player (random): '+game.p(game.s.turn).name);schedule()}
function resume(){onlineStream?.close();onlineSession=null;onlineView=null;try{let s=JSON.parse(localStorageSafe('kaze_deal_save'));game=Object.create(Game.prototype);game.defs=DECK;game.random=Math.random;game.s=s;if(!s.phase)s.phase='play';game.migrateSetup();let availableNames=DealEngine.BOT_NAMES.filter(n=>!game.s.players.slice(1).some(p=>p.name===n));game.shuffle(availableNames);for(let p of game.s.players.slice(1))if(!DealEngine.BOT_NAMES.includes(p.name))p.name=availableNames.pop();save();resetFeedback(s.eventSeq||0);boardPlay=null;lastTurnNotice=null;selected=null;menuOpen=false;render();schedule()}catch{toast('Saved game could not be loaded.')}}
function mutate(fn){try{fn();save();render();schedule()}catch(e){toast(e.message)}}
function groupHTML(g,i){g={...g,cards:g.cards.filter(c=>!pendingArrivals.has(c.id))};if(!g.cards.length)return '';let full=game.full(g);return `<section class="group ${full?'complete':''}" ${i===0?`data-drop-group="${g.id}" data-drop-color="${esc(g.color)}"`:""} style="--c:${COLORS[g.color].hex}"><div class="grouphead"><span>${esc(g.color)}</span><span>${full?'FULL SET':g.cards.length+' / '+COLORS[g.color].size}</span></div><div class="groupcards">${g.cards.map(c=>card(c,i)).join('')}</div><div class="grouprent"><b>Rent ${game.rent(i,g)}M</b><span>${g.house?'<span class="building">House</span> ':''}${g.hotel?'<span class="building">Hotel</span>':''}</span></div></section>`}
function specialHTML(p,i){p={...p,special:p.special.filter(c=>!pendingArrivals.has(c.id))};return p.special.length?`<section class="group specialgroup"><div class="grouphead" style="--c:#a88037"><span>SPECIAL PROPERTIES</span></div><div class="groupcards">${p.special.map(c=>card(c,i)).join('')}</div><div class="grouprent">Active while on your field · 3M each</div></section>`:''}
let boardPlay=null,lastTurnNotice=null;
function announceYourTurn(){let key=game.isSetup()?'simultaneous_setup':(game.s.phase||'play')+':'+game.s.round+":"+game.s.turn;if(game.s.winner!==null||lastTurnNotice===key)return;lastTurnNotice=key;document.querySelector('.your-turn-notice')?.remove();let el=document.createElement('div');el.className='your-turn-notice';el.setAttribute('role','status');el.innerHTML=`<div><span>${game.isSetup()?'SETUP':game.s.turn===0?'YOUR TURN':esc(game.p(game.s.turn).name.toUpperCase())+'’S TURN'}</span><small>${game.isSetup()?'Everyone sets up together · 3 actions each':game.s.turn===0?'Build your empire':'Opponent is playing'}</small></div>`;document.body.append(el);setTimeout(()=>el.remove(),1600)}

function rememberPlay(i,c,mode='play',args={}){boardPlay={owner:i,actor:game.p(i).name,c:{...c},mode,color:game.find(i,c.id)?.group?.color||args.color,target:Number.isInteger(args.target)?game.p(args.target).name:null,extra:args.doubleId?{key:'double_the_rent'}:null};if($('#boardPlay')){$('#boardPlay').innerHTML=boardPlayHTML();fitPlayedCard()}}
function boardPlayHTML(){if(!boardPlay)return '<div class="table-play-empty">PLAY AREA<span>Played cards appear here</span></div>';let b=boardPlay;return `<div class="played-content"><div class="table-play-cards"><button class="played-card-main" onclick="lastPlayedPreview()" aria-label="Preview last played card: ${esc(def(b.c).name)}"><img class="${orientation(b.c,b.owner??0,b.color)}" src="${art(b.c)}" alt="${esc(def(b.c).name)}"></button>${b.extra?`<button class="played-extra" onclick="lastPlayedPreview(true)" aria-label="Preview Double the Rent"><img src="${art(b.extra)}" alt="Double the Rent"></button>`:''}</div><div class="table-play-info"><small>LAST PLAY</small><strong>${esc(b.actor)} ${b.mode==='bank'?'banked':b.mode==='response'?'responded with':'played'}</strong><b>${esc(def(b.c).name)}</b><span>${b.target?'Target: '+esc(b.target):b.mode==='bank'?'Into their bank':'On the table'}</span></div></div>`}

let playedPanelObserver=null,observedPlayedPanel=null;
function fitPlayedCard(){let panel=$('#boardPlay'),content=panel?.querySelector('.played-content');if(!content)return;let cards=[...content.querySelectorAll('.table-play-cards img')],info=content.querySelector('.table-play-info'),width=Math.max(0,panel.clientWidth-12),height=Math.max(0,panel.clientHeight-12);let infoWidth=Math.min(125,Math.max(55,width*.32));if(info)info.style.flexBasis=infoWidth+'px';let cardWidth=Math.max(1,(width-infoWidth-16-Math.max(0,cards.length-1)*5)/Math.max(1,cards.length)),cardHeight=Math.max(1,Math.min(230,height,cardWidth*1.5));for(let img of cards){img.style.height=cardHeight+'px';img.style.width=(cardHeight*2/3)+'px';img.parentElement.style.width=(cardHeight*2/3)+'px';img.parentElement.style.height=cardHeight+'px'}}
function observePlayedPanel(){let panel=$('#boardPlay');if(panel!==observedPlayedPanel){playedPanelObserver?.disconnect();observedPlayedPanel=panel;if(panel&&typeof ResizeObserver!=='undefined'){playedPanelObserver=new ResizeObserver(fitPlayedCard);playedPanelObserver.observe(panel)}}fitPlayedCard()}
window.addEventListener('resize',fitPlayedCard);
function handActions(){let c=selected&&game.p(0).hand.find(c=>c.id===selected.id);if(!c)return '<span class="hand-action-hint">'+(game.isSetup()?'Bank / place cards':'Select a card')+'</span>';let d=def(c),can=game.canAct(0)&&Date.now()>=transferUntil&&!game.s.pending&&game.s.winner===null&&game.used(0)<game.limit(0);return `<strong>${esc(d.name)}</strong>${d.type!=='money'&&(!game.isSetup()||['property','wild','special'].includes(d.type))?`<button class="gold" onclick="playWizard('${c.id}')" ${can?'':'disabled'}>Play card</button>`:''}${!['property','wild','special'].includes(d.type)?`<button onclick="bankCard('${c.id}')" ${can?'':'disabled'}>Bank ${d.value}M</button>`:''}`}

function remaining(i){return (i-game.s.turn+game.s.players.length)%game.s.players.length||game.s.players.length}
function opponent(i){let p=game.p(i);return `<section data-player="${i}" class="opponent ${(game.isSetup()?!p.setupDone:game.s.turn===i)?'active':''}" aria-label="${esc(p.name)}’s board"><div class="ophead"><button class="opponent-open" onclick="viewPlayer(${i})"><span class="avatar">${p.name[0]}</span><strong>${esc(p.name)}</strong><span>${game.isSetup()?(p.setupDone?'✓ Ready':(3-game.used(i))+' setup actions'):game.s.turn===i?'● Playing':'View field ↗'}</span></button><button class="quiet compactbtn" onclick="viewBank(${i})">Bank ${bank(i)}M</button></div><div class="opmeta"><span>▣ ${p.hand.length} cards</span><span>${visibleSets(i)} / 3 sets</span>${p.defending?`<span class="defense">DEFENDING · ${remaining(i)} turns to victory</span>`:''}</div><div class="opponent-field">${p.groups.map(g=>groupHTML(g,i)).join('')+specialHTML(p,i)||'<small>No properties yet</small>'}</div></section>`}

function render(){if(menuOpen||!game)return;prepareTransfers();captureCardPositions();let retainedPlay=$('#boardPlay'),playKey=boardPlay?JSON.stringify(boardPlay):'',keepPlay=retainedPlay?.dataset.playKey===playKey;let s=game.s,p=game.p(0),myturn=game.canAct(0)&&Date.now()>=transferUntil,plays=Math.max(0,game.limit(0)-game.used(0)),last=s.discard.at(-1);$('#root').innerHTML=`<div class="app"><header class="topbar"><div class="brand"><img class="header-logo" src="${ART.logo}" alt="Monopoly Deal Lvl. Up — made by Kaze"></div><span class="turnbanner">${game.isSetup()?'SIMULTANEOUS SETUP · '+(s.players.length-s.setupTurnsLeft)+'/'+s.players.length+' ready':s.winner!==null?'Match complete':s.turn===0?'YOUR TURN':game.p(s.turn).name+'’s turn'}</span><span class="muted" style="font-size:10px">Round ${s.round}</span><button class="quiet" onclick="rules()">Rules</button><button class="quiet" onclick="settings()">⚙</button><button class="quiet" onclick="menu()">Menu</button></header><div class="game"><main class="table"><div class="opponents">${s.players.map((_,i)=>i?opponent(i):'').join('')}</div><section class="shared-board" aria-label="Shared board"><section class="pile-panel" aria-label="Draw and discard piles"><div class="board-pile draw-zone"><div class="deckpile card-back"><img src="${ART.card_back}" alt="Card back"><small>DRAW</small><b>${s.deck.length}</b></div><span>Draw pile</span></div><button class="board-pile discard-zone" onclick="viewDiscard()" aria-label="Browse discard pile, ${s.discard.length} cards">${last?`<img src="${art(last)}" alt="Top discard: ${esc(def(last).name)}">`:'<div class="empty-pile">EMPTY</div>'}<strong>Discard · ${s.discard.length}</strong><span>Click to browse</span></button></section><section class="played-panel" aria-label="Played card"><h3>Played card</h3><div class="board-play" id="boardPlay" aria-live="polite">${boardPlayHTML()}</div></section><aside class="board-side" id="boardSide" aria-live="polite"></aside><small class="no-count">Just Say No: ${s.discard.filter(c=>c.key==='just_say_no').length} discarded · ${s.players.reduce((n,p)=>n+p.bank.filter(c=>c.key==='just_say_no').length,0)} banked / 8</small></section><section class="player-zone" aria-label="Your hand, properties and bank"><div class="center"><div class="property-area"><div class="sectionhead"><strong>YOUR FIELD · ${visibleSets(0)} / 3 SETS</strong>${p.defending?'<span class="defense">DEFENDING</span>':''}</div><div class="field-body"><div class="groups">${p.groups.length||p.special.length?p.groups.map(g=>groupHTML(g,0)).join('')+specialHTML(p,0):'<div class="placeholder"><b>Your empire starts here.</b><br>Choose a property in your hand and play it. Match colors to complete sets.</div>'}${myturn&&!s.pending?'<button class="new-set-drop" data-new-set="true" onclick="rearrange()">＋ New set<br><small>Drag here or choose a card</small></button>':''}</div><button class="bank-field" onclick="viewBank(0)" aria-label="Your bank, ${bank(0)} million"><span>YOUR BANK</span><b>${bank(0)}M</b><div class="bank-cards">${visibleBank(0).slice(-3).map(c=>`<img data-card-id="${c.id}" src="${art(c)}" alt="${esc(def(c).name)}">`).join('')}</div><small>${visibleBank(0).length} cards · view</small></button></div></div></div><section class="handtray"><div class="handwrap"><div class="handhead"><span>${game.isSetup()?'SETUP · ':''}YOUR HAND (${p.hand.length})</span><span>End-turn limit ${game.handLimit(0)}</span></div><div class="hand">${p.hand.filter(c=>!pendingArrivals.has(c.id)).map(c=>card(c,0,'hand')).join('')}</div></div><div class="turncontrols"><div class="hand-actions" id="handActions">${handActions()}</div><div class="pips ${myturn?'':'waiting'}" role="img" aria-label="${myturn?plays+' of '+game.limit(0)+' actions remaining':'Waiting for your turn'}">${Array.from({length:game.limit(0)},(_,i)=>`<span class="pip ${myturn&&i>=plays?'used':''}"></span>`).join('')}</div><button class="gold ${myturn&&plays===0?'end-ready':''}" onclick="endTurn()" ${myturn&&!s.pending?'':'disabled'}>${game.isSetup()?(p.setupDone?'Ready':'Ready · finish setup'):'End Turn'}</button></div></section></section></main><aside class="rail"><section class="preview ${selected?'has-card':''}" id="preview">${preview()}</section><section class="log"><h3>MATCH LOG</h3>${s.log.slice(0,20).map(t=>'<p>'+esc(t)+'</p>').join('')}</section></aside></div></div>`;
if(s.winner!==null){showModal('Empire secured',`<div class="rules"><h2 style="color:#f3c66d">${s.winner===0?'You win!':esc(game.p(s.winner).name)+' wins!'}</h2><p>Three complete sets held through an entire rotation.</p><p>Round ${s.round} · ${s.log.length} recent events</p><button class="gold" onclick="menu()">Back to menu</button></div>`,false);return}
 if(keepPlay&&retainedPlay)$('#boardPlay').replaceWith(retainedPlay);$('#boardPlay').dataset.playKey=playKey;observePlayedPanel();renderPending();renderSidePanel();announceYourTurn();processFeedback();}
function preview(){if(!selected)return '<div class="eyebrow">Card preview</div><p>Select a card to view its artwork.</p>';let d=def(selected);return `<img class="${orientation(selected,selectedOwner,selectedColor)}" src="${art(selected)}" alt="${esc(d.name)}">${selected.locked?'<small>🔒 Permanently '+esc(selected.locked)+'</small>':''}`}

let selectedColor=null;
function setCardPreview(c,owner=0,color=null){selected=c;selectedOwner=owner;selectedColor=color;let panel=$('#preview');if(panel){panel.innerHTML=preview();panel.classList.add('has-card')}if($('#handActions'))$('#handActions').innerHTML=handActions();document.querySelectorAll('.card[data-card-id]').forEach(el=>el.classList.toggle('selected',el.dataset.cardId===c.id));if(innerWidth<=650)panel?.scrollIntoView({block:'nearest',behavior:reduced?'instant':'smooth'})}
function inspect(id,owner,where){let c=findAny(id,owner);if(!c)return;if(where==='bank'){bankCardPreview(c,owner);return}if(where!=='hand'&&!modalLocked)closeModal();setCardPreview(c,owner)}
function lastPlayedPreview(extra=false){if(boardPlay)setCardPreview(extra?boardPlay.extra:boardPlay.c,boardPlay.owner??0,extra?null:boardPlay.color)}
function bankCardPreview(c,owner){closeCardPreview();let el=document.createElement('div');el.id='cardPreviewOverlay';el.className='overlay card-preview-overlay';el.innerHTML=`<section class="bank-art-preview" role="dialog" aria-modal="true" aria-label="Card preview"><button class="quiet bank-preview-close" onclick="closeCardPreview()" aria-label="Close card preview">×</button><img src="${art(c)}" alt="${esc(def(c).name)}"></section>`;el.addEventListener('click',e=>{if(e.target===el)closeCardPreview()});document.body.append(el)}
function opponentCardPreview(c,owner,label){document.querySelector('#cardPreviewOverlay')?.remove();let d=def(c),el=document.createElement('div');el.id='cardPreviewOverlay';el.className='overlay card-preview-overlay';el.innerHTML=`<section class="modal opponent-preview" role="dialog" aria-modal="true" aria-label="${esc(d.name)} preview"><div class="modalhead"><h2>${esc(d.name)}</h2><button class="quiet" onclick="closeCardPreview()" aria-label="Close card preview">×</button></div><div class="bigpreview"><img class="${orientation(c,owner)}" src="${art(c)}" alt="${esc(d.name)}"><div><p class="eyebrow">${esc(label||game.p(owner).name+'’s card')}</p><b>${d.value}M · ${d.type}</b>${c.locked?'<p>🔒 Permanently '+esc(c.locked)+'</p>':''}<button class="quiet" onclick="closeCardPreview()">${label?'Back to board':'Back to opponent’s cards'}</button></div></div></section>`;el.addEventListener('click',e=>{if(e.target===el)closeCardPreview()});document.body.append(el)}
function closeCardPreview(){document.querySelector('#cardPreviewOverlay')?.remove()}
function showModal(title,body,close=true,small=false){$('#dialog').innerHTML=`<div class="overlay"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${esc(title)}</h2>${close?'<button class="quiet" onclick="closeModal()" aria-label="Close">×</button>':''}</div>${body}</section></div>`;modalLocked=!close;}
function closeModal(){if(modalLocked&&game?.s.pending&&!menuOpen)return;$('#dialog').innerHTML='';modalLocked=false}
function bankCard(id){closeModal();mutate(()=>{let c=game.p(0).hand.find(c=>c.id===id);game.play(0,id,'bank');rememberPlay(0,c,'bank');selected=null})}
let wizard=null;
function selectField(name,label,items,value,change=true){return `<label>${label}<select id="w_${name}" ${change?'onchange="wizardChange()"':''}>${items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function visualField(name,label,items,value){let owner=name==='own'?0:Number(wizard.target??1);return `<fieldset class="target-field"><legend>${label}</legend><input type="hidden" id="w_${name}" value="${esc(value)}"><div class="target-options">${items.map(([v,t])=>{let face='';if(name==='property'||name==='own'){let c=findAny(v,owner);if(c)face=`<img class="target-card ${orientation(c,owner)}" src="${art(c)}" alt="${esc(def(c).name)}">`}else if(name==='group'){let g=game.group(game.group(0,v)?0:owner,v);if(g)face=`<div class="target-set">${g.cards.map(c=>`<img class="${orientation(c,game.group(0,v)?0:owner)}" src="${art(c)}" alt="${esc(def(c).name)}">`).join('')}</div>`}else if(name==='target'){let p=game.p(Number(v));face=`<span class="avatar">${esc(p.name[0])}</span><small>${game.sets(Number(v))} complete sets · ${p.hand.length} cards</small><div class="target-set">${game.allProps(Number(v)).slice(0,4).map(c=>`<img src="${art(c)}" alt="${esc(def(c).name)}">`).join('')}</div>`}else if(name==='color'){face=`<span class="color-swatch" style="background:${COLORS[v].hex}"></span>`}else if(name==='category'){let key={property:'mediterranean_avenue',action:'pass_go',money:'money_5m'}[v];face=`<img class="target-card category-card" src="${ART[key]}" alt="${esc(v)} category">`}return `<button type="button" class="target-option ${String(v)===String(value)?'picked':''}" aria-pressed="${String(v)===String(value)}" onclick="wizardPick('${name}',${esc(JSON.stringify(v))})">${face}<span>${esc(t)}</span></button>`}).join('')}</div></fieldset>`}
function wizardPick(key,value){wizard[key]=value;playWizard(wizard.id,true)}
function playWizard(id,refresh=false){let c=game.p(0).hand.find(c=>c.id===id);if(!c)return;let d=def(c);if(!refresh&&(d.type==='special'||['pass_go','its_my_birthday'].includes(c.key)||(['property','wild'].includes(d.type)&&(c.locked||d.colors.length===1)))){wizard={id,...(d.colors?{color:c.locked||d.colors[0]}:{})};submitPlay();return}if(!refresh){wizard={id};if(d.type==='wild'&&!c.locked){let match=game.p(0).groups.filter(g=>d.colors.includes(g.color)&&g.cards.length<COLORS[g.color].size).sort((a,b)=>b.cards.length-a.cards.length)[0];if(match)wizard.color=match.color}}let w=wizard,a={};let fields='',unavailable=false;const get=(k,items)=>{if(!items.some(x=>String(x[0])===String(w[k])))w[k]=items[0]?.[0];return w[k]},field=(key,label,items)=>{if(!items.length){unavailable=true;fields+='<p class="warning">No eligible '+label.toLowerCase()+'.</p>';return}fields+=visualField(key,label,items,get(key,items))};
if(['property','wild'].includes(d.type)){let cols=(c.locked?[c.locked]:d.colors).map(x=>[x,x]);field('color','Assign color',cols);let match=game.p(0).groups.find(g=>g.color===w.color&&g.cards.length<COLORS[g.color].size);w.group=match?.id;fields+='<p class="muted">'+(match?'Automatically joins your '+w.color+' set ('+match.cards.length+'/'+COLORS[w.color].size+').':'Starts a new '+w.color+' set; no matching set has space.')+'</p>';}
let needsTarget=!['property','wild','special','money'].includes(d.type)&&!['pass_go','house','hotel','just_say_no','double_the_rent','its_my_birthday','luxury_tax','i_owe_you'].includes(c.key)&&(d.type!=='rent'||d.any);
if(needsTarget)field('target','Opponent',game.s.players.map((p,i)=>[i,p.name+(p.defending?' · DEFENDING':'')]).filter(([i])=>i!==0&&(c.key!=='tough_luck'||game.sets(i)>=1)));let target=Number(w.target??1);
if(d.type==='rent'||['house','hotel'].includes(c.key)){let gs=game.p(0).groups.filter(g=>d.type==='rent'?(d.any||d.colors.includes(g.color)):(game.full(g)&&!['Railroad','Utility'].includes(g.color)&&!g[c.key]&&(c.key!=='hotel'||g.house)));field('group','Your property set',gs.map(g=>[g.id,`${g.color} · ${g.cards.length}/${COLORS[g.color].size} · Rent ${game.rent(0,g)}M`]));if(d.type==='rent'){fields+='<p class="muted">'+(d.any?'One selected opponent pays.':'Every other player pays.')+' Luxury District adds 1M after doubling; rent reduction applies last.</p>';}}
if(['sly_deal','forced_deal','eviction_notice','forced_rezoning'].includes(c.key)){let ps=game.allProps(target).filter(c=>{let f=game.find(target,c.id);return c.key==='none'?false:['sly_deal','forced_deal'].includes(d.key)?!f.group||!game.full(f.group):d.key==='forced_rezoning'?def(c).type==='wild'&&!c.locked:true});field('property','Opponent property',ps.map(c=>[c.id,`${def(c).name} · ${def(c).value}M${game.find(target,c.id).group?' · '+game.find(target,c.id).group.color:''}`]));if(c.key==='forced_deal')field('own','Your property to give',game.allProps(0).map(c=>[c.id,def(c).name+' · '+def(c).value+'M']));if(c.key==='forced_rezoning'){let f=game.find(target,w.property);field('color','Permanent color',(f?def(f.card).colors:[]).map(c=>[c,c]));}}
if(c.key==='deal_breaker')field('group','Opponent complete set',game.p(target).groups.filter(g=>game.full(g)).map(g=>[g.id,g.color+' · '+g.cards.length+' properties']));if(c.key==='tough_luck')field('category','Take all cards of this type',[['property','Property (including special)'],['action','Action (including rent & buildings)'],['money','Money']]);
if(c.key==='i_owe_you')fields+='<p class="warning">Use this from the payment panel when paying another player, or bank it for 5M.</p>';if(c.key==='just_say_no'||c.key==='double_the_rent')fields+='<p class="warning">'+(c.key==='just_say_no'?'Use this in a response window when targeted.':'Select a Rent card to play it together with Double the Rent.')+'</p>';
if(!fields)fields='<p>'+esc(d.text)+'</p>';
showModal(d.name,`<div class="targeting-layout ${d.type==='wild'?'compact-wild':''}"><aside class="action-reference"><img src="${art(c)}" alt="${esc(d.name)}"><b>${esc(d.name)} · ${d.value}M</b><p>${esc(d.text)}</p></aside><div class="form">${fields}</div></div><p class="muted" style="margin-top:12px">Card value: ${d.value}M · uses ${w.double?2:1} card play${w.double?'s':''}</p><div class="modalfooter"><button class="quiet" onclick="closeModal()">Cancel</button><button class="gold" onclick="submitPlay()" ${unavailable?'disabled':''}>Confirm play</button></div>`,true,false);}
function wizardChange(){for(let e of document.querySelectorAll('[id^="w_"]'))wizard[e.id.slice(2)]=e.type==='checkbox'?e.checked:e.value;playWizard(wizard.id,true)}
function submitPlay(){let w=wizard,candidate=game.p(0).hand.find(c=>c.id===w.id),doub=game.p(0).hand.find(c=>c.key==='double_the_rent');if(candidate&&def(candidate).type==='rent'&&doub&&game.used(0)+2<=game.limit(0)&&!w.doubleAsked&&!w.double){showModal('Double the Rent?',`<div class="rent-double"><img src="${art(doub)}" alt="Double the Rent"><div><p>Use one extra action to double this rent?</p><button class="gold" onclick="rentDouble(true)">Double rent · 2 actions</button><button class="quiet" onclick="rentDouble(false)">Normal rent · 1 action</button></div></div>`,true,true);return}let args={...w,target:w.target!==undefined?Number(w.target):undefined};if(w.double)args.doubleId=game.p(0).hand.find(c=>c.key==='double_the_rent')?.id;try{let c=game.p(0).hand.find(c=>c.id===w.id);game.play(0,w.id,'play',args);rememberPlay(0,c,'play',args);selected=null;closeModal();save();render();schedule()}catch(e){toast(e.message)}}
function rentDouble(yes){wizard.doubleAsked=true;wizard.double=yes;submitPlay()}
function endTurn(){if(Date.now()<transferUntil)return;if(!game.canAct(0)||game.s.pending)return;if(game.isSetup()){finishEndTurn(false);return;}let left=Math.max(0,game.limit(0)-game.s.played);if(!left){finishEndTurn(false);return}showModal('You have '+left+' action'+(left===1?'':'s')+' left',`<div class="rules"><p>Draw <b>${left} card${left===1?'':'s'}</b> instead—one for each unused action—then end your turn. Your hand limit still applies.</p><div class="end-turn-options"><button class="gold" onclick="finishEndTurn(true)">Draw ${left} & end turn</button><button class="quiet" onclick="closeModal()">Continue playing</button><button class="quiet" onclick="finishEndTurn(false)">Pass without drawing</button></div></div>`,true,true)}
function finishEndTurn(draw){closeModal();selected=null;mutate(()=>game.end(0,draw))}
function viewDiscard(){let cards=[...game.s.discard].reverse();showModal('Discard pile · '+cards.length+' cards',`<p class="muted">Newest first. These are the cards currently in the discard pile; reshuffled cards return to the draw pile.</p><label class="discard-search">Find a card<input id="discardSearch" type="search" placeholder="Search card names or types…" oninput="filterDiscard()"></label><div class="discard-browser">${cards.map(c=>`<button class="discard-entry" data-search="${esc((def(c).name+' '+def(c).type).toLowerCase())}" onclick="discardDetails('${c.id}')"><img src="${art(c)}" alt="${esc(def(c).name)}"><strong>${esc(def(c).name)}</strong><span>${def(c).value}M · ${def(c).type}</span></button>`).join('')||'<p>The discard pile is empty.</p>'}</div><p id="discardNoMatches" hidden>No matching cards.</p>`)}
function filterDiscard(){let query=$('#discardSearch').value.trim().toLowerCase(),entries=[...document.querySelectorAll('.discard-entry')];for(let el of entries)el.hidden=!el.dataset.search.includes(query);$('#discardNoMatches').hidden=!entries.length||entries.some(el=>!el.hidden)}
function discardDetails(id){let c=game.s.discard.find(c=>c.id===id);if(c)bankCardPreview(c,0);else viewDiscard()}

function viewBank(i){let p=game.p(i);showModal((i===0?"Your bank · ":p.name+"’s bank · ")+bank(i)+'M',`<p class="muted">Banked action cards are money only and cannot use their action effects.</p><div class="row">${visibleBank(i).map(c=>card(c,i,'bank',90)).join('')||'<p>Empty bank</p>'}</div>`)}
function viewPlayer(i){let p=game.p(i);showModal(p.name+"’s field",`<div class="row" style="margin-bottom:12px"><span class="badge gold">${bank(i)}M bank</span><span class="badge">${p.hand.length} hidden hand cards</span><span class="badge">${game.sets(i)} complete colors</span>${p.defending?'<span class="defense">DEFENDING</span>':''}</div><div class="row">${p.groups.map(g=>groupHTML(g,i)).join('')+specialHTML(p,i)||'<p>No properties</p>'}</div><button class="quiet" style="margin-top:15px" onclick="viewBank(${i})">View bank</button>`)}
let chosen=[];
function renderPending(){let p=game.s.pending;if(transferPlans.size&&Date.now()<transferUntil){if(modalLocked){$('#dialog').innerHTML='';modalLocked=false}return;}if(p?.responder===0)closeCardPreview();if(!p||p.responder!==0){paymentPendingRef=null;if(modalLocked){$('#dialog').innerHTML='';modalLocked=false}return}if(p.kind==='counter'){let e=p.e,has=game.p(0).hand.some(c=>c.key==='just_say_no'),name=e.key==='rent'?'Rent':DECK.find(d=>d.key===e.key)?.name||e.key;let key=e.cardKey||(e.key==='rent'?'rent_any_color':e.key),d=DECK.find(d=>d.key===key);showModal('Your response',`<div class="reaction-layout"><img class="reaction-card" src="${ART[key]||ART.rent_any_color}" alt="${esc(d?.name||name)}"><div class="reaction-content"><h3>Your response</h3><p><b>${esc(game.p(e.actor).name)}</b> played <b>${esc(name)}</b>${e.amount?' · '+e.amount+'M':''} targeting <b>${esc(game.p(e.target).name)}</b>.</p><div class="reaction-buttons"><button class="gold" onclick="answer(false)">${p.negated?'Keep it blocked':'Allow action'}</button><button onclick="answer(true)" ${has?'':'disabled'}>Just Say No ${has?'':'(none in hand)'}</button></div><p>${p.negated?'The action is currently blocked. Counter with Just Say No to restore it.':'Let the action resolve, or block it with Just Say No.'}</p><p class="muted">${esc(d?.text||'')}</p>${e.property?'<p>Target: '+esc(def(game.find(e.target,e.property)?.card||{key:'pass_go'}).name)+'</p>':''}</div></div>`,false,false);$('#dialog .modal').classList.add('reaction-modal');if(e.global)$('#dialog .reaction-content').insertAdjacentHTML('afterbegin','<p class="warning">This action affects everyone. A successful Just Say No cancels it for all players.</p>');return}
if(p.kind==='payment'){if(paymentPendingRef!==p){chosen=[];paymentPendingRef=p}let items=game.payable(0,p.e),sum=items.filter(x=>chosen.includes(x.id)).reduce((n,x)=>n+x.value,0);showModal('Choose payment · '+p.e.amount+'M',`<p>${(p.e.propertyOnly||p.e.key==='compulsory_purchase')?'Properties only.':p.e.key==='luxury_tax'?'Bank first, then properties. Payment goes to discard.':'Choose bank cards or properties. No change is given.'}</p><div id="selectionTotal">${sum}M selected / ${p.e.amount}M owed</div><div id="paymentWarning" class="warning" role="status">${paymentWarning()}</div><div class="payment-modal-groups">${paymentGroups(items)}</div><div class="payment-modal-footer">${!p.e.propertyOnly&&p.e.key!=='luxury_tax'?game.p(0).hand.filter(c=>c.key==='i_owe_you').map(c=>`<button class="iou-pay" onclick="offerIOU('${c.id}')"><img src="${art(c)}" alt="I Owe You"><span>Give I Owe You instead<br><small>Creditor may use Just Say No</small></span></button>`).join(''):''}<div class="dock-buttons"><button class="quiet" onclick="suggestPayment()">Suggest</button><button class="gold" onclick="submitSelection()">Pay selected</button></div></div>`,false);$('#dialog .modal').classList.add('payment-modal');return}if(p.kind==='discard'){chosen=[];let payment=p.kind==='payment',items=payment?game.payable(0,p.e):game.p(0).hand.map(c=>({id:c.id,card:c,zone:'hand',value:def(c).value})),excess=game.p(0).hand.length-game.handLimit(0);let title=payment?'Pay '+p.e.amount+'M':'Discard '+excess+' cards';showModal(title,`<p>${payment?((p.e.propertyOnly||p.e.key==='compulsory_purchase')?'Properties only. You choose what to surrender.':p.e.key==='luxury_tax'?'Pay your bank first, then properties. Payment is discarded.':'Choose bank cards, properties, or buildings to pay. No change is given.'):'Choose cards to discard down to your end-of-turn limit.'}</p><div id="selectionTotal" class="badge gold">Nothing selected</div><div class="choices ${payment?'payment-choices':''}">${items.map(x=>`<label class="choice" id="choice_${x.id}"><input type="checkbox" value="${x.id}" onchange="choose(this)"><img src="${art(x.card)}" alt="${esc(def(x.card).name)}"><strong>${esc(def(x.card).name)}</strong><span>${x.value}M · ${x.zone}</span></label>`).join('')||'<p>No payable assets</p>'}</div><div class="modalfooter">${payment?'<button class="quiet" onclick="suggestPayment()">Suggest payment</button>':''}<button class="gold" onclick="submitSelection()">${payment?'Pay selected':'Discard selected'}</button></div>`,false);}}
function answer(no){mutate(()=>{let c=no?game.p(0).hand.find(c=>c.key==='just_say_no'):null;game.respond(0,no);if(c)rememberPlay(0,c,'response')})}
function choose(el){chosen=Array.from(document.querySelectorAll('.choice input:checked')).map(x=>x.value);document.querySelectorAll('.choice').forEach(e=>e.classList.toggle('checked',e.querySelector('input').checked));let p=game.s.pending;if(p.kind==='payment'){let sum=game.payable(0,p.e).filter(x=>chosen.includes(x.id)).reduce((s,x)=>s+x.value,0);$('#selectionTotal').textContent=sum+'M selected / '+p.e.amount+'M owed';if($('#paymentWarning'))$('#paymentWarning').textContent=paymentWarning()}else $('#selectionTotal').textContent=chosen.length+' / '+(game.p(0).hand.length-game.handLimit(0))+' cards selected'}
function togglePayment(id){chosen=chosen.includes(id)?chosen.filter(x=>x!==id):[...chosen,id];renderPending()}
function suggestPayment(){chosen=game.autoPayment(0,game.s.pending.e);if(game.s.pending.kind==='payment'){renderPending();return}for(let e of document.querySelectorAll('.choice input'))e.checked=chosen.includes(e.value);choose()}
function submitSelection(){try{if(game.s.pending.kind==='payment')game.pay(0,chosen);else game.discard(0,chosen);modalLocked=false;$('#dialog').innerHTML='';save();render();schedule()}catch(e){toast(e.message)}}
let rearr={};
function rearrange(){if(!game.canAct(0)||game.s.pending)return;let cards=game.allProps(0).filter(c=>['property','wild'].includes(def(c).type));showModal('Arrange properties',`<p class="muted">Drag a property onto a matching set on your field, or choose a card below. Rearranging is free on your turn.</p><div class="target-options">${cards.map(c=>`<button class="target-option" onclick="movePicker('${c.id}')"><img class="target-card" src="${art(c)}" alt="${esc(def(c).name)}"><span>${esc(def(c).name)}</span></button>`).join('')||'<p>No color properties to move yet.</p>'}</div><button class="quiet" style="margin-top:15px" onclick="buildingForm()">Move a building</button>`)}
function movePicker(id){let f=game.find(0,id);if(!f||!f.group)return;let c=f.card,cols=c.locked?[c.locked]:def(c).colors,gs=game.p(0).groups.filter(g=>g.id!==f.group.id&&cols.includes(g.color)&&g.cards.length<COLORS[g.color].size);showModal('Move '+def(c).name,`<div class="targeting-layout"><aside class="action-reference"><img src="${art(c)}" alt="${esc(def(c).name)}"><p>Choose a destination. Color locks and set sizes still apply.</p></aside><div><h3>Combine with a set</h3><div class="target-options">${gs.map(g=>`<button class="target-option" onclick="doPropertyMove('${id}','${g.color}','${g.id}')"><div class="target-set">${g.cards.map(c=>`<img src="${art(c)}" alt="${esc(def(c).name)}">`).join('')}</div><span>${g.color} · ${g.cards.length}/${COLORS[g.color].size}</span></button>`).join('')||'<p>No compatible set with space.</p>'}</div><h3 style="margin-top:16px">Start a separate set</h3><div class="target-options">${cols.map(color=>`<button class="target-option" onclick="doPropertyMove('${id}','${color}','')"><span class="color-swatch" style="background:${COLORS[color].hex}"></span><span>${color}</span></button>`).join('')}</div></div></div>`)}
function doPropertyMove(id,color,gid){try{game.move(0,id,color,gid||undefined);selected=null;closeModal();save();render();toast('Property moved.')}catch(e){toast(e.message)}}

function rearrangeForm(refresh=false){let ps=game.allProps(0).filter(c=>def(c).type!=='special');if(!ps.length){toast('Play a property first.');return}if(!rearr.id||!ps.some(c=>c.id===rearr.id))rearr.id=ps[0].id;let c=ps.find(c=>c.id===rearr.id),f=game.find(0,c.id),cols=c.locked?[c.locked]:def(c).colors;if(!cols.includes(rearr.color))rearr.color=f.group.color;let targets=game.p(0).groups.filter(g=>g.id!==f.group.id&&g.color===rearr.color&&g.cards.length<COLORS[g.color].size);showModal('Rearrange · free on your turn',`<div class="form"><label>Property<select id="r_id" onchange="rearrChanged()">${ps.map(c=>`<option value="${c.id}" ${c.id===rearr.id?'selected':''}>${esc(def(c).name)} · ${game.find(0,c.id).group.color}</option>`).join('')}</select></label><label>Color<select id="r_color" onchange="rearrChanged()">${cols.map(x=>`<option ${x===rearr.color?'selected':''}>${x}</option>`).join('')}</select></label><label>Destination<select id="r_group"><option value="">Start a separate ${rearr.color} set</option>${targets.map(g=>`<option value="${g.id}">${g.color} · ${g.cards.length}/${COLORS[g.color].size}</option>`).join('')}</select></label><small>Breaking a set returns its buildings to your hand. Falling below three complete colors cancels your defending status.</small></div><div class="modalfooter"><button class="quiet" onclick="buildingForm()">Move a building</button><button class="gold" onclick="rearrSubmit()">Move property</button></div>`,true,true)}
function rearrChanged(){let id=$('#r_id').value;if(rearr.id!==id){rearr.id=id;rearr.color=game.find(0,id).group.color}else rearr.color=$('#r_color').value;rearrangeForm(true)}
function rearrSubmit(){let id=$('#r_id').value,color=$('#r_color').value,gid=$('#r_group').value;try{game.move(0,id,color,gid);closeModal();save();render()}catch(e){toast(e.message)}}
function buildingForm(){let owned=game.p(0).groups.flatMap(g=>['house','hotel'].filter(k=>g[k]).map(k=>[g.id+'|'+k,g.color+' '+k]));showModal('Move a building · free',`<div class="form">${selectField('building','Building',owned,undefined,false)}${selectField('destination','Destination',game.p(0).groups.filter(g=>game.full(g)&&!['Railroad','Utility'].includes(g.color)).map(g=>[g.id,g.color+' · '+g.id]),undefined,false)}</div><p class="muted">Move a Hotel before moving its House. The destination must be eligible.</p><button class="gold" onclick="buildingSubmit()">Move building</button>`,true,true)}
function buildingSubmit(){let b=$('#w_building')?.value;if(!b){toast('No buildings to move.');return}let[from,key]=b.split('|');try{game.moveBuilding(0,from,$('#w_destination').value,key);closeModal();save();render()}catch(e){toast(e.message)}}
let humanInputUntil=0,transferUntil=0;const botRevealDelay=()=>2000+Math.floor(Math.random()*2001);
document.addEventListener('pointerdown',()=>{humanInputUntil=Date.now()+350},{passive:true});
document.addEventListener('pointerup',()=>{humanInputUntil=Date.now()+120},{passive:true});
function humanInputBusy(){return Date.now()<humanInputUntil||!!touchProperty?.active||!!propertyDrag}
function schedule(){clearTimeout(botTimer);$('#playReveal')?.remove();if(!game||menuOpen||onlineSession||game.s.winner!==null)return;let i;if(game.isSetup()){let bots=game.s.players.map((p,j)=>j>0&&!p.setupDone?j:null).filter(j=>j!==null);if(!bots.length)return;i=bots.find(j=>j>lastSetupBot)??bots[0];lastSetupBot=i}else i=game.s.pending?game.s.pending.responder:game.s.turn;if(i===0)return;if(Date.now()<transferUntil){botTimer=setTimeout(schedule,transferUntil-Date.now()+50);return}botTimer=setTimeout(()=>{if(humanInputBusy()){botTimer=setTimeout(schedule,200);return}try{let plan=game.bot(i,true);if(!plan){botTimer=setTimeout(()=>{if(menuOpen)return;if(humanInputBusy()){schedule();return}game.bot(i);save();render();schedule()},botRevealDelay());return}let c=game.p(i).hand.find(c=>c.id===plan.id),d=def(c),target=plan.args?.target,extra=plan.args?.doubleId?game.p(i).hand.find(c=>c.id===plan.args.doubleId):null;rememberPlay(i,c,plan.response?'response':plan.mode,plan.args);botTimer=setTimeout(()=>{if(menuOpen)return;if(humanInputBusy()){botTimer=setTimeout(schedule,200);return}try{if(plan.response)game.respond(i,true);else game.play(i,plan.id,plan.mode,plan.args);save();render();schedule()}catch(e){console.error(e);toast(e.message)}},botRevealDelay());}catch(e){console.error(e);toast('Bot paused: '+e.message)}},1000)}

function settings(){showModal('Settings',`<div class="form"><p>Bot pace: Relaxed · 3–5 seconds per play</p><label class="check"><input id="soundEnabled" type="checkbox" ${soundEnabled?'checked':''}>Sound effects</label><label class="check"><input id="motion" type="checkbox" ${reduced?'checked':''}>Reduce card animations</label><small>Games save automatically on this browser when local storage is available. No account or internet connection is required.</small><button class="gold" onclick="applySettings()">Apply</button></div>`,true,true)}
function applySettings(){soundEnabled=$('#soundEnabled').checked;localStorageSafe('deal_sound',soundEnabled?'on':'off');if(soundEnabled)unlockAudio();speed=1500;reduced=$('#motion').checked;document.documentElement.classList.toggle('reduce',reduced);let el=$('#motionstyle');if(!el){el=document.createElement('style');el.id='motionstyle';document.head.append(el)}el.textContent=reduced?'*,*::before,*::after{animation:none!important;transition:none!important}':'';localStorageSafe('deal_speed',speed);closeModal();schedule()}
function audit(){showModal('Card library · 71 designs / 130 cards',`<p class="muted">Values shown below come from the same deck data used for payments and bank totals. Portraits use the approved artwork, with values printed on each card.</p><div class="audit">${DECK.map(d=>`<article><img src="${ART[d.key]}" alt="${esc(d.name)}" loading="lazy"><b>${esc(d.name)}</b>${d.value}M · ${d.copies} cop${d.copies===1?'y':'ies'}<p>${esc(d.text)}</p>${d.colors?'<span>'+d.colors.join(' / ')+'</span>':''}</article>`).join('')}</div>`)}
function rules(){showModal('How to play · Lvl. Up rules',`<div class="rules"><h3>Build, then defend</h3><p>Finish your turn with three complete property sets of different colors. Every other player gets a turn. If you maintain at least three complete colors throughout that rotation, you win at the start of your next turn, before drawing. Dropping below three cancels your attempt. Special properties do not form winning sets.</p><h3>Your turn</h3><p>The starting player is chosen randomly for every new game. Start with five cards. Everyone starts together in a simultaneous setup phase with three actions each to bank money/actions or place properties, including specials. Setup grants no extra draw, does not permit action effects or unused-action draws, and always has three actions even with Corporate Headquarters. Each player acts independently and presses Ready when finished. After everyone is ready, normal play begins with the same randomly selected first player. Draw two at the start of each turn, or five if your hand is empty. Play up to three cards: bank money or actions, place properties, or use actions. Corporate Headquarters allows four plays. End your turn with seven cards at most, or nine with Private Vault. Rearranging properties is free on your turn. New properties join an existing matching set with space. When ending early, you may draw one card per unused action and end, continue playing, or pass without drawing. The end-turn hand limit still applies.</p><h3>Properties and rent</h3><p>Brown / Dark Blue / Utility need two cards; Railroad needs four; other colors need three. Use a matching Rent card to charge rent shown by your selected set. Two-color Rent targets every opponent; Any Color Rent targets one. A House adds 3M rent and a Hotel adds a further 4M; these need a complete color set, excluding Railroads and Utilities. The Hotel needs a House first. Double the Rent costs a separate card play. Luxury District adds 1M after doubling; Rent-Controlled Residence reduces the final bill by 2M, minimum zero.</p><h3>Payments and responses</h3><p>The debtor chooses which bank cards, properties or buildings to surrender. No change is given. Pay all eligible assets if unable to cover the bill. Multicolor Wildcards have no payment value and cannot be surrendered. No cards are paid from the hand. Just Say No can block an action affecting you, and another Just Say No can counter that block. Responses do not use turn plays. For all-target actions, all responses resolve before payments; a successful block cancels the entire action for everyone. A banked action can only be money.</p><h3>Custom actions</h3><p><b>Eviction Notice:</b> return an opponent property to their hand, including from a complete set.<br><b>Forced Rezoning:</b> permanently lock an unlocked wildcard to an allowed color. The lock survives ownership and hand changes.<br><b>Compulsory Purchase:</b> one opponent pays at least 5M in properties only, their choice.<br><b>Luxury Tax:</b> every other player discards 5M per complete set they own, bank first, then properties. One successful Just Say No cancels the entire tax for everyone.<br><b>Tough Luck:</b> target an opponent with at least one complete set, then take all cards of a named category (Property, Action, Money) from their hand. Special properties count as Property; Rent and buildings count as Action.</p><h3>Special properties · 3M each</h3><p>One of each of seven specials in the deck. All count as properties for theft, exchange, returns and payments, but do not count as complete sets. Passives stop on leaving your field.<br><b>Insurance Agency:</b> draw one card for each property taken or surrendered in payment to another player, after resolution. Includes specials. If the Agency itself is taken, it still covers that transaction; it does not cover Eviction Notice, your own rearrangement, or property discarded to Luxury Tax.<br><b>Investment Office:</b> draw three instead of two; empty hands still draw five.</p><p><b>Emergency Treasury:</b> at the start of your normal turn, an empty bank creates a new 5M money card directly in your bank. Banked actions count as money. No activation in setup. Generated notes use the normal 5M artwork and may later be paid, discarded or reshuffled.</p><p><b>I Owe You (2 copies, 5M):</b> from your hand during a payment to a player, give this card to their bank instead of the entire bill. Costs no action. The creditor can use Just Say No; if successfully blocked, discard I Owe You and pay the original bill. Countering that block restores the replacement. Works on Compulsory Purchase, but cannot replace Luxury Tax, which goes to discard. May be banked normally for 5M.</p><h3>Local + online edition</h3><p>One human and one to four bots. Bots use the same rules engine; their strategy uses only public fields and their own hand. Your game saves locally. Online rooms support up to five players with optional bots when served by the included Node server. All human players must be ready before the host starts.</p></div>`)}
let lastSetupBot=0,paymentPendingRef=null;
let seenEvent=0,receiptQueue=[],soundEnabled=localStorageSafe('deal_sound')!=='off',soundContext=null;
function resetFeedback(seq){clearFeedback();seenEvent=seq}
function clearFeedback(){lastSetupBot=0;paymentPendingRef=null;receiptQueue=[];feedbackGeneration++;transferPlans.clear();pendingArrivals.clear();transferUntil=0;previousCardRects=new Map();$('#transactionOverlay')?.remove();document.querySelectorAll('.motion-card').forEach(el=>el.remove())}
function unlockAudio(){try{if(!soundContext)soundContext=new (window.AudioContext||window.webkitAudioContext)();if(soundContext.state==='suspended')soundContext.resume()}catch{}}
document.addEventListener('pointerdown',()=>{if(soundEnabled)unlockAudio()},{passive:true});
function soundEffect(kind){if(!soundEnabled||!soundContext||soundContext.state!=='running')return;try{let patterns={draw:[420,600],property:[220,330],bank:[880,1200,1600],play:[300,520,740],charge:[700,950,1200,950],negate:[620,330,160],payment:[900,1250]};let notes=patterns[kind]||patterns.play,t=soundContext.currentTime;for(let i=0;i<notes.length;i++){let osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.type=kind==='negate'?'triangle':'sine';osc.frequency.setValueAtTime(notes[i],t+i*.065);gain.gain.setValueAtTime(0,t+i*.065);gain.gain.linearRampToValueAtTime(.075,t+i*.065+.008);gain.gain.exponentialRampToValueAtTime(.001,t+i*.065+.14);osc.connect(gain);gain.connect(soundContext.destination);osc.start(t+i*.065);osc.stop(t+i*.065+.16)}}catch{}}
let previousCardRects=new Map();
function captureCardPositions(){previousCardRects=new Map();for(let el of document.querySelectorAll('#root [data-card-id]')){let r=el.getBoundingClientRect();if(r.width&&r.height&&r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth)previousCardRects.set(el.dataset.cardId,{left:r.left,top:r.top,width:r.width,height:r.height})}}
function motionCard(c,from,to,back=false,delay=0,duration=500,transfer=false){if(reduced||!from||!to)return Promise.resolve();let a=from.getBoundingClientRect?from.getBoundingClientRect():from,b=to.getBoundingClientRect?to.getBoundingClientRect():to;if(!a.width||!b.width)return Promise.resolve();let w=transfer?72:48,h=w*1.5,el=document.createElement('div');el.className='motion-card'+(back?' card-back':'')+(transfer?' transfer-card':'');el.setAttribute('aria-hidden','true');if(back)el.innerHTML=`<img src="${ART.card_back}" alt="">`;else el.innerHTML=`<img src="${art(c)}" alt="">`;el.style.left=(a.left+a.width/2-w/2)+'px';el.style.top=(a.top+a.height/2-h/2)+'px';document.body.append(el);let dx=b.left+b.width/2-a.left-a.width/2,dy=b.top+b.height/2-a.top-a.height/2,anim=el.animate([{transform:'translate(0,0) rotate(-5deg)',opacity:1},{offset:.45,transform:`translate(${dx*.45}px,${dy*.45-28}px) rotate(3deg)`,opacity:1},{transform:`translate(${dx}px,${dy}px) rotate(0deg)`,opacity:1}],{duration,delay,easing:'cubic-bezier(.3,.05,.3,1)',fill:'both'});return new Promise(resolve=>{let finished=false;const done=()=>{if(finished)return;finished=true;el.remove();resolve()};anim.onfinish=done;anim.oncancel=done;setTimeout(done,duration+delay+250)})}
function bankSurface(i){return i===0?$('.bank-field'):document.querySelector(`[data-player="${i}"] .compactbtn`)}
function propertySurface(i){return i===0?$('.property-area'):playerSurface(i)}
let pendingArrivals=new Map(),transferPlans=new Map(),feedbackGeneration=0;
function visibleBank(i){return game.p(i).bank.filter(c=>!pendingArrivals.has(c.id))}
function visibleSets(i){return new Set(game.p(i).groups.map(g=>({...g,cards:g.cards.filter(c=>!pendingArrivals.has(c.id))})).filter(g=>game.full(g)).map(g=>g.color)).size}
function prepareTransfers(){for(let e of (game.s.events||[]).filter(e=>e.seq>seenEvent&&['transfer','payment','discard'].includes(e.type))){if(transferPlans.has(e.seq))continue;let start=Math.max(Date.now(),transferUntil),end=reduced?Date.now():start+(e.cards.length?1600+(e.cards.length-1)*320:0);transferPlans.set(e.seq,{start,end});transferUntil=end;if(['payment','discard'].includes(e.type))receiptQueue=[];if(!reduced&&Number.isInteger(e.target)&&e.type!=='discard')for(let c of e.cards)pendingArrivals.set(c.id,e.target)}}
function transferCards(e){let plan=transferPlans.get(e.seq)||{start:Date.now()},generation=feedbackGeneration,motions=[];for(let n=0;n<e.cards.length;n++){let c=e.cards[n],property=['property','wild','special'].includes(def(c).type)||e.destination==='field',from=previousCardRects.get(c.id)||(e.replacement||e.type==='discard'?playerSurface(e.actor):property?propertySurface(e.actor):bankSurface(e.actor)),to=e.target===null||e.type==='discard'?$('.discard-zone'):e.destination==='hand'?playerSurface(e.target):property?propertySurface(e.target):bankSurface(e.target);motions.push(motionCard(c,from,to,false,Math.max(0,plan.start-Date.now())+n*320,1600,true))}Promise.all(motions).then(()=>{if(generation!==feedbackGeneration||menuOpen)return;for(let c of e.cards)pendingArrivals.delete(c.id);transferPlans.delete(e.seq);if(['payment','discard'].includes(e.type))receiptQueue=[e];render();schedule()})}

function playerSurface(i){return i===0?$('.hand'):document.querySelector(`[data-player="${i}"]`)}
function processFeedback(){let events=(game.s.events||[]).filter(e=>e.seq>seenEvent);if(!events.length)return;seenEvent=game.s.eventSeq||events.at(-1).seq;let audible=null;for(let e of events){if(e.type==='draw'){e.cards.slice(0,3).forEach((c,n)=>motionCard(c,$('.draw-zone'),playerSurface(e.actor),e.actor!==0,n*70));audible=audible||'draw'}else if(['bank','property','play','negate'].includes(e.type)){let dest=e.type==='bank'?(e.actor===0?$('.bank-field'):document.querySelector(`[data-player="${e.actor}"]`)):e.type==='property'?(e.actor===0?$('.property-area'):document.querySelector(`[data-player="${e.actor}"]`)):$('#boardPlay');motionCard(e.card,previousCardRects.get(e.card.id)||(e.passive?(e.actor===0?$('.property-area'):playerSurface(e.actor)):playerSurface(e.actor)),dest);audible=e.type==='play'&&game.d(e.card).type==='rent'?'charge':e.type}else if(e.type==='charge'){audible='charge'}else if(e.type==='transfer'){transferCards(e);audible='payment'}else if(e.type==='payment'||e.type==='discard'){transferCards(e);audible='payment'}}if(audible)soundEffect(audible);showReceipt()}
function showReceipt(){renderSidePanel()}
function renderSidePanel(){let panel=$('#boardSide');if(!panel||!game)return;panel.innerHTML=`<h3>Payment activity</h3><div class="activity-list">${receiptQueue.map(e=>{let name=game.p(e.actor).name,target=e.target===null||e.type==='discard'?'Discard pile':game.p(e.target).name,title=e.type==='discard'?name+' discarded':e.target===0?name+' paid you':name+' paid '+target;return `<article class="activity-item"><b>${esc(title)}</b><small>${esc(name)} → ${esc(target)}${e.amount!==undefined?' · '+e.amount+'M':''}</small><div class="activity-cards">${e.cards.map(c=>`<img src="${art(c)}" alt="${esc(def(c).name)}" title="${esc(def(c).name)} · ${def(c).value}M">`).join('')||'<small>No payable cards</small>'}</div></article>`}).join('')||'<p class="muted">Payments and discards appear here automatically.</p>'}</div>`}
function offerIOU(id){mutate(()=>game.owe(0,id))}
function paymentWarning(){let colors=game.p(0).groups.filter(g=>game.full(g)&&g.cards.some(c=>chosen.includes(c.id))).map(g=>g.color);return colors.length?'Warning: this payment breaks your '+colors.join(', ')+' full set'+(colors.length>1?'s':'')+(game.p(0).defending?' and may end your defense.':'.'):''}
function paymentGroups(items){let banks=items.filter(x=>x.zone==='bank'),props=items.filter(x=>x.zone!=='bank'),groups=new Map(),sort=xs=>xs.sort((a,b)=>a.value-b.value||def(a.card).name.localeCompare(def(b.card).name)),tiles=xs=>sort(xs).map(x=>`<button type="button" class="choice ${chosen.includes(x.id)?'checked':''}" data-payment-id="${x.id}" aria-pressed="${chosen.includes(x.id)}" onclick="togglePayment('${x.id}')"><img class="${orientation(x.card,0)}" src="${art(x.card)}" alt="${esc(def(x.card).name)}"><strong>${esc(def(x.card).name)}</strong><span>${x.value}M</span></button>`).join('');for(let x of props){let f=game.find(0,x.id),color=f?.special?'Special properties':f?.group?.color||game.group(0,x.group)?.color||'Other properties';if(!groups.has(color))groups.set(color,[]);groups.get(color).push(x)}return `${banks.length?`<section class="payment-section payment-bank"><h3>Bank</h3><div class="choices payment-card-row">${tiles(banks)}</div></section>`:''}${props.length?`<section class="payment-section payment-properties"><h3>Properties</h3><div class="payment-colors">${[...groups.keys()].sort().map(color=>`<section class="payment-color" style="--payment-color:${COLORS[color]?.hex||'#bc984c'}"><h4>${esc(color)}</h4><div class="choices payment-card-row">${tiles(groups.get(color))}</div></section>`).join('')}</div></section>`:''}${!items.length?'<p>No payable assets.</p>':''}`}
window.addEventListener('keydown' ,e=>{if(e.key==='Escape'){if($('#cardPreviewOverlay'))closeCardPreview();else if(!modalLocked)closeModal()}});menu();

let propertyDrag=null,touchProperty=null,skipPropertyClickUntil=0;
function canArrange(){return game&&!menuOpen&&game.canAct(0)&&Date.now()>=transferUntil&&!game.s.pending&&game.s.winner===null}
function clearPropertyDrag(){document.querySelectorAll('.drop-ok,.drop-hover').forEach(el=>el.classList.remove('drop-ok','drop-hover'));$('#propertyGhost')?.remove();propertyDrag=null}
function beginPropertyDrag(id){if(!canArrange())return false;let f=game.find(0,id);if(!f?.group)return false;propertyDrag=id;let cols=f.card.locked?[f.card.locked]:def(f.card).colors;document.querySelectorAll('[data-drop-group]').forEach(el=>{let g=game.group(0,el.dataset.dropGroup);el.classList.toggle('drop-ok',g.id!==f.group.id&&cols.includes(g.color)&&g.cards.length<COLORS[g.color].size)});document.querySelector('[data-new-set]')?.classList.add('drop-ok');return true}
function dropProperty(target){let id=propertyDrag,el=target?.closest('[data-drop-group],[data-new-set]');clearPropertyDrag();if(!id||!el||!canArrange())return;if(el.dataset.newSet){movePicker(id);return}let g=game.group(0,el.dataset.dropGroup);if(g)doPropertyMove(id,g.color,g.id)}
document.addEventListener('dragstart',e=>{let el=e.target.closest('[data-prop]');if(!el)return;if(!beginPropertyDrag(el.dataset.prop)){e.preventDefault();return}e.dataTransfer.setData('text/plain',propertyDrag);e.dataTransfer.effectAllowed='move'});
document.addEventListener('dragover',e=>{if(!propertyDrag)return;let el=e.target.closest('[data-drop-group],[data-new-set]');if(el?.classList.contains('drop-ok')){e.preventDefault();e.dataTransfer.dropEffect='move'}});
document.addEventListener('drop',e=>{if(!propertyDrag)return;e.preventDefault();skipPropertyClickUntil=Date.now()+400;dropProperty(e.target)});
document.addEventListener('dragend',clearPropertyDrag);
document.addEventListener('pointerdown',e=>{if(!canArrange())return;let el=e.target.closest('[data-prop]');if(el)touchProperty={id:el.dataset.prop,x:e.clientX,y:e.clientY,active:false,pointer:e.pointerId}});
document.addEventListener('pointermove',e=>{let t=touchProperty;if(!t||e.pointerId!==t.pointer)return;if(!t.active&&Math.hypot(e.clientX-t.x,e.clientY-t.y)>8){if(!beginPropertyDrag(t.id)){touchProperty=null;return}t.active=true;let im=document.createElement('img');im.id='propertyGhost';im.src=art(game.find(0,t.id).card);document.body.append(im)}if(t.active){e.preventDefault();let ghost=$('#propertyGhost');ghost.style.left=(e.clientX-35)+'px';ghost.style.top=(e.clientY-45)+'px';let hit=document.elementFromPoint(e.clientX,e.clientY),group=hit?.closest('[data-drop-group],[data-new-set]');document.querySelectorAll('.drop-hover').forEach(el=>el.classList.remove('drop-hover'));if(group?.classList.contains('drop-ok'))group.classList.add('drop-hover');let area=document.querySelector('.property-area .groups'),r=area?.getBoundingClientRect();if(r&&e.clientY>=r.top&&e.clientY<=r.bottom){if(e.clientX>r.right-35)area.scrollLeft+=12;if(e.clientX<r.left+35)area.scrollLeft-=12}}},{passive:false});
document.addEventListener('pointerup',e=>{let t=touchProperty;touchProperty=null;if(t?.active){skipPropertyClickUntil=Date.now()+500;dropProperty(document.elementFromPoint(e.clientX,e.clientY))}});
document.addEventListener('pointercancel',()=>{touchProperty=null;clearPropertyDrag()});
document.addEventListener('click',e=>{if(Date.now()<skipPropertyClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
